style.css:
body {
    color: #7ea0d8 !important;
    background-image: url("https://i.ibb.co/Q7CfMb9W/fondo-compu.jpg") !important;
    background-size: cover !important;
    background-position: center !important;
    background-attachment: fixed !important;
    background-repeat: no-repeat !important;
}

h1,
h2,
h3,
h4,
h5,
h6 {
    color: #a8c7ff !important;
}

a {
    color: #4da6ff !important;
}

a:hover {
    color: #b36bff !important;
}

input,
textarea {
    color: #000000 !important;
    -webkit-text-fill-color: #000000 !important;
}

input::placeholder,
textarea::placeholder {
    color: #555555 !important;
    -webkit-text-fill-color: #555555 !important;
}

input,
textarea,
select {
    background: #ffffff !important;
    color: #000000 !important;
    border: 1px solid #7b3fa1 !important;
    border-radius: 6px !important;
}

button,
input[type="button"],
input[type="submit"],
input[type="reset"],
[role="button"] {
    background: linear-gradient(90deg, #e60087, #7b3fa1, #174fa3) !important;
    color: #ffffff !important;
    border: 1px solid #ff4db8 !important;
    border-radius: 8px !important;
}

button:hover,
input[type="button"]:hover,
input[type="submit"]:hover,
[role="button"]:hover {
    filter: brightness(1.25) !important;
}

::selection {
    background: #e60087 !important;
    color: #ffffff !important;
}

::-webkit-scrollbar {
    width: 10px;
}

::-webkit-scrollbar-track {
    background: #080808;
}

::-webkit-scrollbar-thumb {
    background: #7b3fa1;
    border-radius: 10px;
}

nav,
aside,
[role="navigation"],
[data-sidebar],
[class*="sidebar"],
[id*="sidebar"] {
    background: rgba(8, 8, 8, 0.94) !important;
    color: #ff4db8 !important;
    border-color: #7b3fa1 !important;
}

nav a,
aside a,
[role="navigation"] a,
[data-sidebar] a,
[class*="sidebar"] a,
[id*="sidebar"] a {
    color: #ff4db8 !important;
}

nav a:hover,
aside a:hover,
[role="navigation"] a:hover,
[data-sidebar] a:hover,
[class*="sidebar"] a:hover,
[id*="sidebar"] a:hover {
    background: linear-gradient(90deg, #e60087, #7b3fa1, #174fa3) !important;
    color: #ffffff !important;
    border-radius: 8px !important;
}

nav button,
aside button,
[role="navigation"] button,
[data-sidebar] button,
[class*="sidebar"] button,
[id*="sidebar"] button {
    background: transparent !important;
    color: #ff4db8 !important;
}

nav button:hover,
aside button:hover,
[role="navigation"] button:hover,
[data-sidebar] button:hover,
[class*="sidebar"] button:hover,
[id*="sidebar"] button:hover {
    background: linear-gradient(90deg, #e60087, #7b3fa1, #174fa3) !important;
    color: #ffffff !important;
}

header,
[role="banner"] {
    background: rgba(8, 8, 8, 0.94) !important;
    color: #ff4db8 !important;
    border-color: #7b3fa1 !important;
}

header a,
[role="banner"] a {
    color: #ff4db8 !important;
}

header a:hover,
[role="banner"] a:hover {
    color: #b36bff !important;
}

[role="menu"],
[role="dialog"],
[role="listbox"] {
    background: #100b14 !important;
    color: #ff4db8 !important;
    border-color: #7b3fa1 !important;
}

[role="menu"] a,
[role="listbox"] a {
    color: #ff4db8 !important;
}

[role="menu"] a:hover,
[role="listbox"] a:hover {
    color: #b36bff !important;
}

[role="search"] {
    background: #100b14 !important;
    color: #7ea0d8 !important;
}
